package msm_test.entity;

import java.util.EnumSet;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.PathfinderMob;
import net.minecraft.world.entity.ai.goal.Goal;
import net.minecraft.world.entity.monster.RangedAttackMob;

/**
 * The {@code ranged_attack} goal (ADR 0070 D5): walks towards the target until it is within {@code range} and in sight,
 * aims for {@code chargeTicks} with the mob's {@code aggressive} flag set (so a renderer can pose it), then calls
 * {@link RangedAttackMob#performRangedAttack}. {@code intervalTicks} is the time from one shot to the next, aiming
 * included; the first shot comes after the aim alone. A shot needs the target in sight and within {@code range};
 * losing sight for three seconds while aiming stops the aim. With {@code strafe} the mob circles the target in range
 * as a skeleton does ({@code RangedBowAttackGoal}'s strafing, same numbers).
 *
 * <p>Vanilla's bow and crossbow goals accept only monsters, hence this goal for every kind of mob.
 */
public class MobRangedAttackGoal<T extends PathfinderMob & RangedAttackMob> extends Goal {
    /** Ticks in sight before the mob stops walking (vanilla {@code RangedAttackGoal}'s 5). */
    private static final int SEE_TO_STOP = 5;
    /** Ticks in sight before a strafing mob stops walking and starts to circle ({@code RangedBowAttackGoal}'s 20). */
    private static final int SEE_TO_STRAFE = 20;
    /** Ticks out of sight that end an aim ({@code RangedBowAttackGoal}'s 60). */
    private static final int LOST_SIGHT = -60;

    private final T mob;
    private final double speed;
    private final int chargeTicks;
    private final int intervalTicks;
    private final float rangeSqr;
    private final boolean strafe;

    private int seeTime;
    /** Ticks aimed so far, or -1 when not aiming. */
    private int charge = -1;
    /** Ticks until the next aim may start. */
    private int cooldown;
    private boolean strafingClockwise;
    private boolean strafingBackwards;
    private int strafingTime = -1;

    public MobRangedAttackGoal(T mob, double speed, int chargeTicks, int intervalTicks, float range, boolean strafe) {
        this.mob = mob;
        this.speed = speed;
        this.chargeTicks = Math.max(0, chargeTicks);
        this.intervalTicks = Math.max(1, intervalTicks);
        this.rangeSqr = range * range;
        this.strafe = strafe;
        setFlags(EnumSet.of(Flag.MOVE, Flag.LOOK));
    }

    public boolean strafes() {
        return strafe;
    }

    public boolean isCharging() {
        return charge >= 0;
    }

    @Override
    public boolean canUse() {
        LivingEntity target = mob.getTarget();
        return target != null && target.isAlive();
    }

    @Override
    public boolean canContinueToUse() {
        return canUse() || !mob.getNavigation().isDone();
    }

    @Override
    public void start() {
        super.start();
        seeTime = 0;
        charge = -1;
    }

    @Override
    public void stop() {
        super.stop();
        mob.setAggressive(false);
        seeTime = 0;
        charge = -1;
        strafingTime = -1;
        mob.getNavigation().stop();
    }

    @Override
    public boolean requiresUpdateEveryTick() {
        return true;
    }

    @Override
    public void tick() {
        LivingEntity target = mob.getTarget();
        if (target == null) {
            return;
        }
        double distSqr = mob.distanceToSqr(target.getX(), target.getY(), target.getZ());
        boolean inSight = mob.getSensing().hasLineOfSight(target);
        if (inSight != seeTime > 0) {
            seeTime = 0;
        }
        seeTime += inSight ? 1 : -1;
        boolean inRange = distSqr <= rangeSqr;

        if (inRange && seeTime >= (strafe ? SEE_TO_STRAFE : SEE_TO_STOP)) {
            mob.getNavigation().stop();
            if (strafe) {
                strafingTime++;
            }
        } else {
            mob.getNavigation().moveTo(target, speed);
            strafingTime = -1;
        }
        if (strafingTime >= 20) {
            if (mob.getRandom().nextFloat() < 0.3) {
                strafingClockwise = !strafingClockwise;
            }
            if (mob.getRandom().nextFloat() < 0.3) {
                strafingBackwards = !strafingBackwards;
            }
            strafingTime = 0;
        }
        if (strafingTime > -1) {
            if (distSqr > rangeSqr * 0.75f) {
                strafingBackwards = false;
            } else if (distSqr < rangeSqr * 0.25f) {
                strafingBackwards = true;
            }
            mob.getMoveControl().strafe(strafingBackwards ? -0.5f : 0.5f, strafingClockwise ? 0.5f : -0.5f);
            mob.lookAt(target, 30.0f, 30.0f);
        } else {
            mob.getLookControl().setLookAt(target, 30.0f, 30.0f);
        }

        if (cooldown > 0) {
            cooldown--;
        }
        if (charge >= 0) {
            if (!inSight && seeTime < LOST_SIGHT) {
                endCharge();
            } else if (inSight && inRange && ++charge >= chargeTicks) {
                shoot(target);
            }
        } else if (cooldown <= 0 && inSight && inRange) {
            charge = 0;
            mob.setAggressive(true);
            if (chargeTicks == 0) {
                shoot(target);
            }
        }
    }

    private void shoot(LivingEntity target) {
        endCharge();
        mob.performRangedAttack(target, 1.0f);
        cooldown = Math.max(0, intervalTicks - chargeTicks);
    }

    private void endCharge() {
        charge = -1;
        mob.setAggressive(false);
    }
}
